/// The gallery's example of `ToolRail`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_separator = args.bool("separator");

        let open = State::new(args.number("open") as _);
        {
            let mut it = ToolRail::new(
                open.binding(),
                [(IconName::Type, "Text"), (IconName::ZoomIn, "Zoom"), (IconName::Layers, "Fades")],
            );
            if arg_separator {
                it = it.separator();
            }
            it
        }
        // Hold the button, right-click or press Right for the tools that share its place.
        .separator()
        .tool(ToolRailItem::new(IconName::Square, "Shape").variant(IconName::Circle, "Ellipse"))
    })
}

impl ComponentBook for ToolRail {
    fn book() -> Meta {
        Meta::new("Forms/ToolRail", render)
            .summary("A narrow bar of tools with their names under their icons.")
            .arg(ArgType::bool("separator", false))
            .arg(ArgType::number("open", 0.0, 0.0, 5.0, 1.0).description("How the example starts."))
            .story("Example", Args::new())
    }
}
